insert into public.translations (locale, key, value) values
  ('pt-BR', 'gateway.baseUrl.hint.litellm', $json$"O endereço do seu proxy LiteLLM, por exemplo http://localhost:4000/v1."$json$::jsonb),
  ('en', 'gateway.baseUrl.hint.litellm', $json$"The address of your LiteLLM proxy, for example http://localhost:4000/v1."$json$::jsonb),
  ('es', 'gateway.baseUrl.hint.litellm', $json$"La dirección de tu proxy LiteLLM, por ejemplo http://localhost:4000/v1."$json$::jsonb),
  ('zh-CN', 'gateway.baseUrl.hint.litellm', $json$"你的 LiteLLM 代理地址，例如 http://localhost:4000/v1。"$json$::jsonb),
  ('hi', 'gateway.baseUrl.hint.litellm', $json$"आपके LiteLLM प्रॉक्सी का पता, जैसे http://localhost:4000/v1।"$json$::jsonb),
  ('ar', 'gateway.baseUrl.hint.litellm', $json$"عنوان وكيل LiteLLM الخاص بك، مثل http://localhost:4000/v1."$json$::jsonb),
  ('fr', 'gateway.baseUrl.hint.litellm', $json$"L’adresse de votre proxy LiteLLM, par exemple http://localhost:4000/v1."$json$::jsonb),
  ('ru', 'gateway.baseUrl.hint.litellm', $json$"Адрес вашего прокси LiteLLM, например http://localhost:4000/v1."$json$::jsonb),
  ('ja', 'gateway.baseUrl.hint.litellm', $json$"LiteLLM プロキシのアドレス（例: http://localhost:4000/v1）。"$json$::jsonb),
  ('de', 'gateway.baseUrl.hint.litellm', $json$"Die Adresse deines LiteLLM-Proxys, zum Beispiel http://localhost:4000/v1."$json$::jsonb),
  ('pt-BR', 'docs.gatewayProviders.usage', $json$"Em Configurações › OpenRouter ou LiteLLM, informe o endereço base e a chave de API (OpenRouter: openrouter.ai/api/v1; LiteLLM: o seu proxy, por exemplo http://localhost:4000/v1, chave opcional), ligue o agente, salve, depois Conferir conexão e Atualizar modelos. A chave fica neste computador e nunca é sincronizada. As organizações liberam ou bloqueiam cada um na política de LLM."$json$::jsonb),
  ('en', 'docs.gatewayProviders.usage', $json$"In Settings › OpenRouter or LiteLLM, enter the base URL and the API key (OpenRouter: openrouter.ai/api/v1; LiteLLM: your proxy, for example http://localhost:4000/v1, key optional), turn the agent on, save, then Check connection and Refresh models. The key stays on this computer and is never synced. Organizations can allow or block each one in the LLM policy."$json$::jsonb),
  ('es', 'docs.gatewayProviders.usage', $json$"En Ajustes › OpenRouter o LiteLLM, indica la URL base y la clave de API (OpenRouter: openrouter.ai/api/v1; LiteLLM: tu proxy, por ejemplo http://localhost:4000/v1, clave opcional), activa el agente, guarda y luego Comprobar conexión y Actualizar modelos. La clave se queda en este equipo y nunca se sincroniza. Las organizaciones permiten o bloquean cada uno en la política de LLM."$json$::jsonb),
  ('zh-CN', 'docs.gatewayProviders.usage', $json$"在 设置 › OpenRouter 或 LiteLLM 中填写基础地址和 API 密钥（OpenRouter：openrouter.ai/api/v1；LiteLLM：你的代理，例如 http://localhost:4000/v1，密钥可选），启用智能体并保存，然后点击“检查连接”和“刷新模型”。密钥保存在这台电脑上，不会同步。组织可在 LLM 策略中允许或阻止每一个。"$json$::jsonb),
  ('hi', 'docs.gatewayProviders.usage', $json$"सेटिंग › OpenRouter या LiteLLM में बेस URL और API कुंजी दर्ज करें (OpenRouter: openrouter.ai/api/v1; LiteLLM: आपका प्रॉक्सी, जैसे http://localhost:4000/v1, कुंजी वैकल्पिक), एजेंट चालू करें, सहेजें, फिर कनेक्शन जाँचें और मॉडल अपडेट करें। कुंजी इसी कंप्यूटर पर रहती है और कभी सिंक नहीं होती। संगठन LLM नीति में हर एक को अनुमति दे सकते हैं या रोक सकते हैं।"$json$::jsonb),
  ('ar', 'docs.gatewayProviders.usage', $json$"في الإعدادات › OpenRouter أو LiteLLM أدخل العنوان الأساسي ومفتاح API (OpenRouter: openrouter.ai/api/v1؛ LiteLLM: وكيلك مثل http://localhost:4000/v1 والمفتاح اختياري)، فعّل الوكيل واحفظ، ثم «فحص الاتصال» و«تحديث النماذج». يبقى المفتاح على هذا الحاسوب ولا يُزامَن أبدًا. يمكن للمؤسسات السماح بكل منهما أو حظره في سياسة LLM."$json$::jsonb),
  ('fr', 'docs.gatewayProviders.usage', $json$"Dans Réglages › OpenRouter ou LiteLLM, saisissez l’URL de base et la clé d’API (OpenRouter : openrouter.ai/api/v1 ; LiteLLM : votre proxy, par exemple http://localhost:4000/v1, clé facultative), activez l’agent, enregistrez, puis Vérifier la connexion et Actualiser les modèles. La clé reste sur cet ordinateur et n’est jamais synchronisée. Les organisations autorisent ou bloquent chacun dans la politique LLM."$json$::jsonb),
  ('ru', 'docs.gatewayProviders.usage', $json$"В Настройки › OpenRouter или LiteLLM укажите базовый URL и API-ключ (OpenRouter: openrouter.ai/api/v1; LiteLLM: ваш прокси, например http://localhost:4000/v1, ключ необязателен), включите агента, сохраните, затем нажмите «Проверить подключение» и «Обновить модели». Ключ остаётся на этом компьютере и никогда не синхронизируется. Организации разрешают или блокируют каждого в политике LLM."$json$::jsonb),
  ('ja', 'docs.gatewayProviders.usage', $json$"設定 › OpenRouter または LiteLLM でベース URL と API キーを入力し（OpenRouter: openrouter.ai/api/v1、LiteLLM: ご自身のプロキシ（例: http://localhost:4000/v1）、キーは任意）、エージェントを有効にして保存し、「接続を確認」と「モデルを更新」を実行します。キーはこのコンピューターに残り、同期されません。組織は LLM ポリシーでそれぞれを許可またはブロックできます。"$json$::jsonb),
  ('de', 'docs.gatewayProviders.usage', $json$"Gib unter Einstellungen › OpenRouter oder LiteLLM die Basis-URL und den API-Schlüssel ein (OpenRouter: openrouter.ai/api/v1; LiteLLM: dein Proxy, zum Beispiel http://localhost:4000/v1, Schlüssel optional), schalte den Agenten ein, speichere und wähle dann Verbindung prüfen und Modelle aktualisieren. Der Schlüssel bleibt auf diesem Computer und wird nie synchronisiert. Organisationen erlauben oder blockieren jeden in der LLM-Richtlinie."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.providerIcons.title', $json$"Ícones oficiais e integração conferida"$json$::jsonb),
  ('en', 'whatsNew.item.providerIcons.title', $json$"Official icons and checked integrations"$json$::jsonb),
  ('es', 'whatsNew.item.providerIcons.title', $json$"Iconos oficiales e integraciones comprobadas"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.providerIcons.title', $json$"官方图标与核对过的集成"$json$::jsonb),
  ('hi', 'whatsNew.item.providerIcons.title', $json$"आधिकारिक आइकन और जाँची हुई इंटीग्रेशन"$json$::jsonb),
  ('ar', 'whatsNew.item.providerIcons.title', $json$"الأيقونات الرسمية وتكاملات تم التحقق منها"$json$::jsonb),
  ('fr', 'whatsNew.item.providerIcons.title', $json$"Icônes officielles et intégrations vérifiées"$json$::jsonb),
  ('ru', 'whatsNew.item.providerIcons.title', $json$"Официальные значки и проверенные интеграции"$json$::jsonb),
  ('ja', 'whatsNew.item.providerIcons.title', $json$"公式アイコンと確認済みの連携"$json$::jsonb),
  ('de', 'whatsNew.item.providerIcons.title', $json$"Offizielle Icons und geprüfte Integrationen"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter e LiteLLM agora usam os ícones oficiais. A integração foi conferida com a documentação de cada um: o Kilo roda com `kilo run --model provedor/modelo --auto` e lista os modelos com `kilo models`; o OpenRouter e o LiteLLM usam /chat/completions e /models com a chave Bearer. O endereço padrão do LiteLLM passou a ser http://localhost:4000/v1, como na documentação dele; endereços já salvos continuam valendo."$json$::jsonb),
  ('en', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter and LiteLLM now use their official icons. The integration was checked against each one's documentation: Kilo runs with `kilo run --model provider/model --auto` and lists models with `kilo models`; OpenRouter and LiteLLM use /chat/completions and /models with the Bearer key. LiteLLM's default address is now http://localhost:4000/v1, as in its documentation; addresses you already saved keep working."$json$::jsonb),
  ('es', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter y LiteLLM ahora usan sus iconos oficiales. La integración se comprobó con la documentación de cada uno: Kilo se ejecuta con `kilo run --model proveedor/modelo --auto` y lista los modelos con `kilo models`; OpenRouter y LiteLLM usan /chat/completions y /models con la clave Bearer. La dirección predeterminada de LiteLLM ahora es http://localhost:4000/v1, como en su documentación; las direcciones ya guardadas siguen funcionando."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code、OpenRouter 和 LiteLLM 现在使用各自的官方图标。集成已对照各自的文档核对：Kilo 通过 `kilo run --model 提供商/模型 --auto` 运行，并用 `kilo models` 列出模型；OpenRouter 和 LiteLLM 使用带 Bearer 密钥的 /chat/completions 与 /models。LiteLLM 的默认地址现为 http://localhost:4000/v1（与其文档一致），已保存的地址仍然有效。"$json$::jsonb),
  ('hi', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter और LiteLLM अब अपने आधिकारिक आइकन इस्तेमाल करते हैं। इंटीग्रेशन को हर एक के दस्तावेज़ों से जाँचा गया: Kilo `kilo run --model प्रदाता/मॉडल --auto` से चलता है और `kilo models` से मॉडल सूचीबद्ध करता है; OpenRouter और LiteLLM Bearer कुंजी के साथ /chat/completions और /models इस्तेमाल करते हैं। LiteLLM का डिफ़ॉल्ट पता अब http://localhost:4000/v1 है, जैसा उसके दस्तावेज़ में है; पहले से सहेजे पते चलते रहेंगे।"$json$::jsonb),
  ('ar', 'whatsNew.item.providerIcons.detail', $json$"تستخدم Kilo Code وOpenRouter وLiteLLM الآن أيقوناتها الرسمية. جرى التحقق من التكامل مع وثائق كل منها: يعمل Kilo بالأمر `kilo run --model المزود/النموذج --auto` ويعرض النماذج بالأمر `kilo models`؛ ويستخدم OpenRouter وLiteLLM المسارين /chat/completions و/models مع مفتاح Bearer. أصبح العنوان الافتراضي لـ LiteLLM هو http://localhost:4000/v1 كما في وثائقه، وتبقى العناوين المحفوظة صالحة."$json$::jsonb),
  ('fr', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter et LiteLLM utilisent désormais leurs icônes officielles. L’intégration a été vérifiée avec la documentation de chacun : Kilo s’exécute avec `kilo run --model fournisseur/modèle --auto` et liste les modèles avec `kilo models` ; OpenRouter et LiteLLM utilisent /chat/completions et /models avec la clé Bearer. L’adresse par défaut de LiteLLM est maintenant http://localhost:4000/v1, comme dans sa documentation ; les adresses déjà enregistrées continuent de fonctionner."$json$::jsonb),
  ('ru', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter и LiteLLM теперь используют официальные значки. Интеграция сверена с документацией каждого: Kilo запускается командой `kilo run --model провайдер/модель --auto` и выводит модели через `kilo models`; OpenRouter и LiteLLM используют /chat/completions и /models с ключом Bearer. Адрес LiteLLM по умолчанию теперь http://localhost:4000/v1, как в его документации; сохранённые ранее адреса продолжают работать."$json$::jsonb),
  ('ja', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code、OpenRouter、LiteLLM が公式アイコンを使うようになりました。連携は各ドキュメントと照合済みです。Kilo は `kilo run --model プロバイダー/モデル --auto` で動作し、`kilo models` でモデルを一覧表示します。OpenRouter と LiteLLM は Bearer キー付きの /chat/completions と /models を使います。LiteLLM の既定アドレスはドキュメントどおり http://localhost:4000/v1 になりました。保存済みのアドレスはそのまま使えます。"$json$::jsonb),
  ('de', 'whatsNew.item.providerIcons.detail', $json$"Kilo Code, OpenRouter und LiteLLM verwenden jetzt ihre offiziellen Icons. Die Integration wurde mit der Dokumentation der jeweiligen Dienste geprüft: Kilo läuft mit `kilo run --model Anbieter/Modell --auto` und listet Modelle mit `kilo models`; OpenRouter und LiteLLM nutzen /chat/completions und /models mit dem Bearer-Schlüssel. Die Standardadresse von LiteLLM ist jetzt http://localhost:4000/v1, wie in seiner Dokumentation; bereits gespeicherte Adressen funktionieren weiter."$json$::jsonb)
